mapper.select:
SELECT apt_cmplex_no
FROM mgmt_office
WHERE mgmt_ofc_no = #{mgmtOfcNo}

mapper.sql:
/* 1. 관리사무소 공지 일정 조회 */ SELECT BI.APT_CMPLEX_NO /** 아파트단지번호 */ , P.ANN_NO AS SCHEDULE_NO /** 일정번호 */ , 'NOTICE' AS SCHEDULE_TY /** 일정유형코드 */ , '공지' AS SCHEDULE_TY_NM /** 일정유형명 */ , P.TTL AS SCHEDULE_TTL /** 일정제목 */ , DBMS_LOB.SUBSTR(P.CN, 1000, 1) AS SCHEDULE_CN /** 일정내용 */ , '관리사무소' AS LOC_CN /** 장소내용 */ , TO_CHAR(NVL(P.PBLANC_BGNG_DT, P.REG_DTTM), 'YYYY-MM-DD') AS START_DT /** 일정시작일 */ , TO_CHAR(NVL(P.PBLANC_END_DT, NVL(P.PBLANC_BGNG_DT, P.REG_DTTM)), 'YYYY-MM-DD') AS END_DT /** 일정종료일 */ , CASE WHEN P.TOP_FIX_YN = 'Y' THEN 'RED' ELSE 'BLUE' END AS COLOR_CD /** 캘린더색상코드 */ , P.WRTR_ID AS RGTR_ID /** 등록자아이디 */ , NULL AS USER_NO /** 사용자번호 */ , NULL AS USER_NM /** 사용자명 */ FROM APT_ANN_BOARD_POST P INNER JOIN APT_BOARD_INSTANCE BI ON P.BOARD_NO = BI.BOARD_NO /** 게시판번호 연결 */ WHERE BI.APT_CMPLEX_NO = #{aptCmplexNo} /** 아파트단지번호 */ AND BI.USE_YN = 'Y' /** 게시판사용여부 */ AND P.DEL_YN = 'N' /** 삭제여부 */
/* 공지 시작일이 조회 월의 마지막 날보다 작거나 같으면 조회 대상 */ AND NVL(P.PBLANC_BGNG_DT, P.REG_DTTM) <= TO_DATE(#{monthEndDt}, 'YYYY-MM-DD')
/* 공지 종료일이 조회 월의 시작 날보다 크거나 같으면 조회 대상 */ AND NVL(P.PBLANC_END_DT, NVL(P.PBLANC_BGNG_DT, P.REG_DTTM)) >= TO_DATE(#{monthStartDt}, 'YYYY-MM-DD')
UNION ALL
/* 2. 단지 내 행사/공사 일정 조회 */ /* 주의: COMPLEX_SCHEDULE 테이블에 별도 시작일/종료일 컬럼이 없어서 REG_DT 기준으로 표시 */ SELECT CS.APT_CMPLEX_NO /** 아파트단지번호 */ , CS.SCHEDULE_NO /** 일정번호 */ , CASE WHEN CS.SCHDL_TTL LIKE '%공사%' THEN 'CONSTRUCTION' ELSE 'EVENT' END AS SCHEDULE_TY /** 일정유형코드 */ , CASE WHEN CS.SCHDL_TTL LIKE '%공사%' THEN '공사' ELSE '행사' END AS SCHEDULE_TY_NM /** 일정유형명 */ , CS.SCHDL_TTL AS SCHEDULE_TTL /** 일정제목 */ , CS.SCHDL_CN AS SCHEDULE_CN /** 일정내용 */ , CS.LOC_CN AS LOC_CN /** 장소내용 */ , TO_CHAR(CS.REG_DT, 'YYYY-MM-DD') AS START_DT /** 일정시작일 */ , TO_CHAR(CS.REG_DT, 'YYYY-MM-DD') AS END_DT /** 일정종료일 */ , CASE WHEN CS.SCHDL_TTL LIKE '%공사%' THEN 'ORANGE' ELSE 'GREEN' END AS COLOR_CD /** 캘린더색상코드 */ , CS.RGTR_ID AS RGTR_ID /** 등록자아이디 */ , NULL AS USER_NO /** 사용자번호 */ , NULL AS USER_NM /** 사용자명 */ FROM COMPLEX_SCHEDULE CS WHERE CS.APT_CMPLEX_NO = #{aptCmplexNo} /** 아파트단지번호 */ AND CS.REG_DT BETWEEN TO_DATE(#{monthStartDt}, 'YYYY-MM-DD') AND TO_DATE(#{monthEndDt}, 'YYYY-MM-DD') + 0.99999
UNION ALL
/* 3. 직원 휴가 일정 조회 */ SELECT MO.APT_CMPLEX_NO /** 아파트단지번호 */ , VS.VACATION_SCHDL_NO AS SCHEDULE_NO /** 일정번호 */ , 'VACATION' AS SCHEDULE_TY /** 일정유형코드 */ , '직원휴가' AS SCHEDULE_TY_NM /** 일정유형명 */ , VS.SCHDL_TTL AS SCHEDULE_TTL /** 일정제목 */ , M.USER_NM || ' 직원 휴가' AS SCHEDULE_CN /** 일정내용 */ , '관리사무소' AS LOC_CN /** 장소내용 */ , TO_CHAR(VS.SCHDL_BGNG_DT, 'YYYY-MM-DD') AS START_DT /** 일정시작일 */ , TO_CHAR(VS.SCHDL_END_DT, 'YYYY-MM-DD') AS END_DT /** 일정종료일 */ , NVL(VS.COLOR_CD, 'PURPLE') AS COLOR_CD /** 캘린더색상코드 */ , M.USER_ID AS RGTR_ID /** 등록자아이디 */ , VS.USER_NO AS USER_NO /** 사용자번호 */ , M.USER_NM AS USER_NM /** 사용자명 */ FROM MNGR_VACATION_SCHDL VS INNER JOIN MANAGER MG ON VS.USER_NO = MG.USER_NO /** 관리자 사용자번호 연결 */ INNER JOIN MGMT_OFFICE MO ON MG.MGMT_OFC_NO = MO.MGMT_OFC_NO /** 관리사무소번호 연결 */ INNER JOIN MEMBER M ON VS.USER_NO = M.USER_NO /** 회원 사용자번호 연결 */ WHERE MO.APT_CMPLEX_NO = #{aptCmplexNo} /** 아파트단지번호 */ AND MO.USE_YN = 'Y' /** 관리사무소사용여부 */
/* 휴가 시작일이 조회 월의 마지막 날보다 작거나 같으면 조회 대상 */ AND VS.SCHDL_BGNG_DT <= TO_DATE(#{monthEndDt}, 'YYYY-MM-DD')
/* 휴가 종료일이 조회 월의 시작 날보다 크거나 같으면 조회 대상 */ AND VS.SCHDL_END_DT >= TO_DATE(#{monthStartDt}, 'YYYY-MM-DD')
UNION ALL
/* 4. 검침 일정 조회 */ /* 검침 데이터 중복 제거 왜 사용? 세대별 검침 이력이 많으면 같은 날짜/같은 시설 검침이 수백 건 출력되므로 시설 + 검침일 기준으로 1건만 캘린더 일정에 표시합니다. */ SELECT F.APT_CMPLEX_NO , 'METER_' || F.FACILITY_NO || '_' || TO_CHAR(TRUNC(MH.METER_DT), 'YYYYMMDD') AS SCHEDULE_NO , 'METER' AS SCHEDULE_TY , '검침' AS SCHEDULE_TY_NM , F.FACILITY_NM || ' 검침' AS SCHEDULE_TTL , COUNT(*) || '건 검침 완료' AS SCHEDULE_CN , F.LOC_CN AS LOC_CN , TO_CHAR(TRUNC(MH.METER_DT), 'YYYY-MM-DD') AS START_DT , TO_CHAR(TRUNC(MH.METER_DT), 'YYYY-MM-DD') AS END_DT , 'SKY' AS COLOR_CD , NULL AS RGTR_ID , NULL AS USER_NO , NULL AS USER_NM FROM METER_HSTRY MH INNER JOIN FACILITY F ON MH.FACILITY_NO = F.FACILITY_NO WHERE F.APT_CMPLEX_NO = #{aptCmplexNo} AND F.USE_YN = 'Y' AND MH.METER_DT BETWEEN TO_DATE(#{monthStartDt}, 'YYYY-MM-DD') AND TO_DATE(#{monthEndDt}, 'YYYY-MM-DD') + 0.99999 GROUP BY F.APT_CMPLEX_NO , F.FACILITY_NO , F.FACILITY_NM , F.LOC_CN , TRUNC(MH.METER_DT)
UNION ALL
/* 5. 점검 일정 조회 */ SELECT F.APT_CMPLEX_NO /** 아파트단지번호 */ , FH.FAC_CHK_HSTRY_NO AS SCHEDULE_NO /** 일정번호 */ , 'CHECK' AS SCHEDULE_TY /** 일정유형코드 */ , '점검' AS SCHEDULE_TY_NM /** 일정유형명 */ , F.FACILITY_NM || ' 점검' AS SCHEDULE_TTL /** 일정제목 */ , FH.CHK_CN AS SCHEDULE_CN /** 일정내용 */ , F.LOC_CN AS LOC_CN /** 장소내용 */ , TO_CHAR(FH.CHK_DT, 'YYYY-MM-DD') AS START_DT /** 일정시작일 */ , TO_CHAR(FH.CHK_DT, 'YYYY-MM-DD') AS END_DT /** 일정종료일 */ , 'GRAY' AS COLOR_CD /** 캘린더색상코드 */ , NULL AS RGTR_ID /** 등록자아이디 */ , NULL AS USER_NO /** 사용자번호 */ , NULL AS USER_NM /** 사용자명 */ FROM FACILITY_CHECK_HSTRY FH INNER JOIN FACILITY F ON FH.FACILITY_NO = F.FACILITY_NO /** 시설번호 연결 */ WHERE F.APT_CMPLEX_NO = #{aptCmplexNo} /** 아파트단지번호 */ AND F.USE_YN = 'Y' /** 시설사용여부 */ AND FH.CHK_DT BETWEEN TO_DATE(#{monthStartDt}, 'YYYY-MM-DD') AND TO_DATE(#{monthEndDt}, 'YYYY-MM-DD') + 0.99999

mapper.select:
/* kr.or.ddit.domain.apt.mgmtOffice.main.mapper.IAptScheduleCalendarMapper.selectScheduleCalendarList */ /* 단지 일정 캘린더 월별 일정 목록 조회 */
SELECT CAL.APT_CMPLEX_NO /** 아파트단지번호 */ , CAL.SCHEDULE_NO /** 일정번호 */ , CAL.SCHEDULE_TY /** 일정유형코드 */ , CAL.SCHEDULE_TY_NM /** 일정유형명 */ , CAL.SCHEDULE_TTL /** 일정제목 */ , CAL.SCHEDULE_CN /** 일정내용 */ , CAL.LOC_CN /** 장소내용 */ , CAL.START_DT /** 일정시작일 */ , CAL.END_DT /** 일정종료일 */ , CAL.COLOR_CD /** 캘린더색상코드 */ , CAL.RGTR_ID /** 등록자아이디 */ , CAL.USER_NO /** 사용자번호 */ , CAL.USER_NM /** 사용자명 */ FROM (
) CAL WHERE 1 = 1
AND CAL.SCHEDULE_TY = #{scheduleTy} /** 일정유형 검색 */
AND ( UPPER(CAL.SCHEDULE_TTL) LIKE '%' || UPPER(#{keyword}) || '%' /** 일정제목 검색 */ OR UPPER(CAL.SCHEDULE_CN) LIKE '%' || UPPER(#{keyword}) || '%' /** 일정내용 검색 */ OR UPPER(CAL.LOC_CN) LIKE '%' || UPPER(#{keyword}) || '%' /** 장소 검색 */ OR UPPER(CAL.USER_NM) LIKE '%' || UPPER(#{keyword}) || '%' /** 직원명 검색 */ )
ORDER BY CAL.START_DT ASC /** 일정시작일 오름차순 */ , CAL.SCHEDULE_TY ASC /** 일정유형 오름차순 */ , CAL.SCHEDULE_TTL ASC /** 일정제목 오름차순 */

SELECT COUNT(*) FROM (
) CAL WHERE 1 = 1
AND CAL.SCHEDULE_TY = #{scheduleTy}
AND ( UPPER(CAL.SCHEDULE_TTL) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(CAL.SCHEDULE_CN) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(CAL.LOC_CN) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(CAL.USER_NM) LIKE '%' || UPPER(#{keyword}) || '%' )

/* kr.or.ddit.domain.apt.mgmtOffice.main.mapper.IAptScheduleCalendarMapper.selectScheduleCalendarStat */ /* 단지 일정 캘린더 통계 조회 */
SELECT COUNT(*) AS TOTAL_CNT /** 전체일정수 */ , SUM( CASE WHEN TO_CHAR(SYSDATE, 'YYYY-MM-DD') BETWEEN START_DT AND END_DT THEN 1 ELSE 0 END ) AS TODAY_CNT /** 오늘일정수 */ , COUNT(*) AS MONTH_CNT /** 월간일정수 */ , SUM( CASE WHEN SCHEDULE_TY = 'VACATION' THEN 1 ELSE 0 END ) AS VACATION_CNT /** 직원휴가일정수 */ FROM ( SELECT CAL.APT_CMPLEX_NO /** 아파트단지번호 */ , CAL.SCHEDULE_NO /** 일정번호 */ , CAL.SCHEDULE_TY /** 일정유형코드 */ , CAL.SCHEDULE_TY_NM /** 일정유형명 */ , CAL.SCHEDULE_TTL /** 일정제목 */ , CAL.SCHEDULE_CN /** 일정내용 */ , CAL.LOC_CN /** 장소내용 */ , CAL.START_DT /** 일정시작일 */ , CAL.END_DT /** 일정종료일 */ , CAL.COLOR_CD /** 캘린더색상코드 */ , CAL.RGTR_ID /** 등록자아이디 */ , CAL.USER_NO /** 사용자번호 */ , CAL.USER_NM /** 사용자명 */ FROM (
) CAL WHERE 1 = 1
AND CAL.SCHEDULE_TY = #{scheduleTy} /** 일정유형 검색 */
AND ( UPPER(CAL.SCHEDULE_TTL) LIKE '%' || UPPER(#{keyword}) || '%' /** 일정제목 검색 */ OR UPPER(CAL.SCHEDULE_CN) LIKE '%' || UPPER(#{keyword}) || '%' /** 일정내용 검색 */ OR UPPER(CAL.LOC_CN) LIKE '%' || UPPER(#{keyword}) || '%' /** 장소 검색 */ OR UPPER(CAL.USER_NM) LIKE '%' || UPPER(#{keyword}) || '%' /** 직원명 검색 */ )
)

/* kr.or.ddit.domain.apt.mgmtOffice.main.mapper.IAptScheduleCalendarMapper.selectNextVacationScheduleNo */
/* 직원 휴가 일정번호 채번 */

SELECT
    'VAC' || LPAD(SEQ_MNGR_VACATION_SCHDL.NEXTVAL, 6, '0')    /** 휴가일정번호 */
FROM DUAL

SELECT * FROM ( SELECT A.*, ROWNUM RN FROM ( SELECT CAL.APT_CMPLEX_NO, CAL.SCHEDULE_NO, CAL.SCHEDULE_TY, CAL.SCHEDULE_TY_NM, CAL.SCHEDULE_TTL, CAL.SCHEDULE_CN, CAL.LOC_CN, CAL.START_DT, CAL.END_DT, CAL.COLOR_CD, CAL.RGTR_ID, CAL.USER_NO, CAL.USER_NM FROM (
) CAL WHERE 1 = 1
AND CAL.SCHEDULE_TY = #{scheduleTy}
AND ( UPPER(CAL.SCHEDULE_TTL) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(CAL.SCHEDULE_CN) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(CAL.LOC_CN) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(CAL.USER_NM) LIKE '%' || UPPER(#{keyword}) || '%' )
ORDER BY CAL.START_DT ASC, CAL.SCHEDULE_TY ASC, CAL.SCHEDULE_TTL ASC ) A WHERE ROWNUM <= #{endRow} ) WHERE RN >= #{startRow}

mapper.insert:
/* kr.or.ddit.domain.apt.mgmtOffice.main.mapper.IAptScheduleCalendarMapper.insertVacationSchedule */
/* 직원 휴가 일정 등록 */

INSERT INTO MNGR_VACATION_SCHDL (
                                  VACATION_SCHDL_NO      /** 휴가일정번호 */
                                , SCHDL_BGNG_DT          /** 일정시작일자 */
                                , SCHDL_END_DT           /** 일정종료일자 */
                                , SCHDL_TTL              /** 일정제목 */
                                , COLOR_CD               /** 캘린더색상코드 */
                                , REG_DT                 /** 등록일자 */
                                , USER_NO                /** 사용자번호 */
) VALUES (
           #{scheduleNo}
         , TO_DATE(#{startDt}, 'YYYY-MM-DD')
         , TO_DATE(#{endDt}, 'YYYY-MM-DD')
         , #{scheduleTtl}
         , NVL(#{colorCd}, 'PURPLE')
         , SYSDATE
         , #{userNo}
         )

mapper.delete:
/* kr.or.ddit.domain.apt.mgmtOffice.main.mapper.IAptScheduleCalendarMapper.deleteVacationSchedule */
/* 직원 휴가 일정 삭제 */

DELETE FROM MNGR_VACATION_SCHDL
WHERE VACATION_SCHDL_NO = #{scheduleNo}     /** 휴가일정번호 */
  AND USER_NO IN (
    SELECT
        USER_NO                       /** 사용자번호 */
    FROM MANAGER
    WHERE MGMT_OFC_NO = #{mgmtOfcNo}   /** 관리사무소번호 */
)
